import{_ as t,o,c as a,ae as r}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"Mutability Is Contract or Input, Never Stored Output","description":"","frontmatter":{"id":"9870790320","title":"Mutability Is Contract or Input, Never Stored Output","state":"Approved","created":"2026-08-03T00:00:00.000Z","tags":["schema","api-design","mutability","naming","taxonomy"],"category":"Platform"},"headers":[],"relativePath":"adrs/9870790320/README.md","filePath":"adrs/9870790320/README.md"}'),i={name:"adrs/9870790320/README.md"};function n(s,e,d,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mutability-is-contract-or-input-never-stored-output" tabindex="-1">Mutability Is Contract or Input, Never Stored Output <a class="header-anchor" href="#mutability-is-contract-or-input-never-stored-output" aria-label="Permalink to &quot;Mutability Is Contract or Input, Never Stored Output&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Once a mutation-authority field exists (<a href="./../8779742261/README.html">ADR#8779742261</a>), the same design itch recurs: &quot;should we also add <code>immutable: true</code>? or <code>deletable: false</code>?&quot; The itch is understandable, the answer is no, and the major API platforms have a per-se convention that says exactly where each kind of mutability knowledge belongs. This ADR records that convention so the question stops being re-asked per product.</p><p>The core confusion is between three different kinds of fact that all get casually called &quot;immutability&quot;:</p><ol><li>A <strong>field-level rule</strong>: &quot;this property can never change after creation&quot; (true for every row).</li><li>A <strong>row-level derived capability</strong>: &quot;this particular row cannot be deleted right now&quot; (a conclusion computed from authority, invariants, and flags).</li><li>A <strong>row-level independent input</strong>: &quot;the owner asked for a safety latch on this row&quot; (a fact someone set, derivable from nothing).</li></ol><p>Storing kind 1 or kind 2 as a column creates a second source of truth for a rule that already has one, makes contradictory states representable (<code>managed_by: system, immutable: false</code>?), and flattens many causes with many remedies into a single unexplained bit.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>Chosen option: &quot;declare field rules in the API contract, compute derived capabilities into responses, store only independent inputs&quot;, because this is verifiably what the platform vendors themselves do, and it is the only arrangement in which no stored value can drift from the rule it describes.</p><h3 id="_1-field-level-mutability-is-api-contract-metadata" tabindex="-1">1. Field-level mutability is API-contract metadata <a class="header-anchor" href="#_1-field-level-mutability-is-api-contract-metadata" aria-label="Permalink to &quot;1. Field-level mutability is API-contract metadata&quot;">​</a></h3><p>Google&#39;s public API rulebook (the AIP system, google.aip.dev) defines <code>google.api.field_behavior</code> annotations declared on the field in the contract, not stored in any row: <code>IMMUTABLE</code> (&quot;A field on a resource cannot be changed after its creation&quot;), <code>OUTPUT_ONLY</code> (&quot;The field is provided in responses, but... including the field in a message in a request does nothing&quot;), <code>INPUT_ONLY</code>, <code>REQUIRED</code>, <code>IDENTIFIER</code> (AIP-203). Azure&#39;s equivalent is the <code>x-ms-mutability</code> OpenAPI extension, an array of <code>create</code> | <code>read</code> | <code>update</code> on the property definition, e.g. <code>&quot;x-ms-mutability&quot;: [&quot;create&quot;, &quot;read&quot;]</code> for a set-once property.</p><p>Applied to a mutation-authority field: <code>managed_by</code> is contract-level <code>IMMUTABLE</code> (its value is assigned at birth and never changes through the API), declared in the OpenAPI/schema definition, enforced by the API layer, and backstopped by database triggers (<a href="./../8779742261/README.html">ADR#8779742261</a>). Nothing about that requires or tolerates a per-row <code>immutable</code> column.</p><h3 id="_2-row-level-derived-capabilities-are-computed-response-fields" tabindex="-1">2. Row-level derived capabilities are computed response fields <a class="header-anchor" href="#_2-row-level-derived-capabilities-are-computed-response-fields" aria-label="Permalink to &quot;2. Row-level derived capabilities are computed response fields&quot;">​</a></h3><p>&quot;Can this row be deleted?&quot; is a question whose answer is derived at request time from the authority field, invariants (e.g. a last-admin guard), protection flags, and referential integrity. The precedented shape is a computed, read-only field in the API response (the <code>viewerCanDelete</code> pattern; in AIP terms, an <code>OUTPUT_ONLY</code> field), so a client can gray out a button without the server ever persisting the conclusion. A stored <code>deletable</code> column is this pattern done wrong: it conflates causes (system-managed? protected? blocked by an invariant?) and goes stale the moment any input changes.</p><h3 id="_3-row-level-independent-inputs-are-stored-flags" tabindex="-1">3. Row-level independent inputs are stored flags <a class="header-anchor" href="#_3-row-level-independent-inputs-are-stored-flags" aria-label="Permalink to &quot;3. Row-level independent inputs are stored flags&quot;">​</a></h3><p>The only mutability-adjacent facts that belong in storage are the ones that are inputs, set by an authority and derivable from nothing:</p><ul><li><strong>Owner safety latches</strong>: GCP&#39;s <code>deletionProtectionEnabled</code> (verified on Filestore instances), AWS termination protection. The owner sets it, the owner clears it, deletion checks read it.</li><li><strong>Per-object reconciliation opt-outs</strong>: Kubernetes&#39; <code>rbac.authorization.k8s.io/autoupdate: &quot;false&quot;</code> annotation on default RBAC objects (<a href="./../0289186035/README.html">ADR#0289186035</a>, mode 3).</li></ul><p>The test for any proposed flag: <strong>is it an independent degree of freedom someone sets, or is it derivable from existing fields?</strong> Store inputs; compute outputs; never store an output next to its inputs.</p><h3 id="which-vendor-to-follow-per-se" tabindex="-1">Which vendor to follow, per se <a class="header-anchor" href="#which-vendor-to-follow-per-se" aria-label="Permalink to &quot;Which vendor to follow, per se&quot;">​</a></h3><p>Google is the only major cloud that publishes a complete, versioned, public rule system for these questions (the AIPs: resource names in AIP-122, field behavior in AIP-203), and its rules are the ones this ADR adopts where they exist. Azure&#39;s REST guidelines and <code>x-ms-mutability</code> corroborate the same split (contract metadata, not row data) and serve as the second reference. AWS exhibits the same patterns in its APIs (verb-level rejections for system-managed resources, attribution fields, stored protection toggles) but publishes no equivalent public rulebook, so it serves as pattern evidence rather than a rule source.</p><h3 id="summary-decision-table" tabindex="-1">Summary decision table <a class="header-anchor" href="#summary-decision-table" aria-label="Permalink to &quot;Summary decision table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fact</th><th>Where it lives</th><th>Precedent</th></tr></thead><tbody><tr><td>&quot;This field never changes after create&quot;</td><td>API contract annotation (<code>IMMUTABLE</code> / <code>x-ms-mutability</code>), enforced at the write path, DB triggers as backstop</td><td>AIP-203, Azure autorest</td></tr><tr><td>&quot;This row is owned by X&quot;</td><td>The stored authority enum (<code>managed_by</code>)</td><td>ADR#8779742261</td></tr><tr><td>&quot;Can the caller delete/edit this row right now&quot;</td><td>Computed <code>OUTPUT_ONLY</code> response field</td><td><code>viewerCan*</code> pattern, AIP-203</td></tr><tr><td>&quot;The owner asked for a deletion guard&quot;</td><td>Stored boolean input flag</td><td>GCP <code>deletionProtectionEnabled</code>, AWS termination protection</td></tr><tr><td>&quot;Skip reconciling this built-in object&quot;</td><td>Stored per-object opt-out marker</td><td>Kubernetes <code>autoupdate</code> annotation</td></tr><tr><td>&quot;This row is read-only&quot; as a stored column</td><td>Nowhere, ever</td><td>The anti-pattern this ADR exists to reject</td></tr></tbody></table><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../8779742261/README.html">ADR#8779742261: Actor and Authority Taxonomy</a></li><li><a href="./../0289186035/README.html">ADR#0289186035: Built-In Resources and Their Modes</a></li><li><a href="https://google.aip.dev/203" target="_blank" rel="noreferrer">AIP-203: Field behavior documentation</a></li><li><a href="https://google.aip.dev/122" target="_blank" rel="noreferrer">AIP-122: Resource names</a></li><li><a href="https://github.com/Azure/autorest/blob/main/docs/extensions/readme.md" target="_blank" rel="noreferrer">Azure autorest <code>x-ms-mutability</code></a></li><li><a href="https://kubernetes.io/docs/reference/access-authn-authz/rbac/" target="_blank" rel="noreferrer">Kubernetes default RBAC auto-reconciliation</a></li></ul>',23)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
